/-
# Correctness of a 3-SAT to Jigsaw Puzzle Reduction

This file formalizes a reduction from Boolean satisfiability of 3-CNF formulas to
the solvability of a jigsaw puzzle, and proves its correctness:

  `correctness : Satisfiable φ ↔ Solvable (mkPuzzle φ)`.

## Model

* `EdgeType` — the shape of one side of a piece: `flat`, `tab`, or `blank`.
  Complementary shapes mate: `tab ↔ blank`, and `flat ↔ flat`.  `complement` is an
  involution.
* `Piece` — four edges plus an identifier.
* `Placement` — a piece put at a grid coordinate with a `Rotation`.
* `HFits` / `VFits` — two adjacent placements fit when their shared edges are
  complementary.
* `IsRectAssembly` — a board that covers a rectangular grid, has flat boundary
  edges, and whose adjacent pieces all fit.
* `Puzzle` / `Solvable` — a bag of pieces with dimensions together with a list of
  clause constraints.  A puzzle is solvable when there is a valid assembly built
  from the available pieces that, in addition, satisfies every clause constraint
  (the "OR-fitting" of a clause piece: at least one variable cell exposes the edge
  matching one of the clause's literals).

## Reduction

For a formula `φ` with `n = φ.numVars` variables we build an `n × 2` puzzle:

* the **top row** holds one of two *variable pieces* per column, `varPiece i true`
  or `varPiece i false`, whose bottom edge encodes the chosen truth value
  (`true ↦ tab`, `false ↦ blank`);
* the **bottom row** holds a *base piece* whose top edge must complement the
  variable piece above it (so the assembly is rigid in each column), and whose
  bottom edge is flat (the grid boundary).

The clause constraints read the truth values off the top row.  A satisfying
assignment yields a valid assembly and vice-versa.
-/
import Mathlib

namespace JigsawSAT

/-! ## Edges -/

/-- The shape of one side of a jigsaw piece. -/
inductive EdgeType where
  | flat | tab | blank
deriving DecidableEq, Repr, Fintype

/-- The mating shape: `tab` mates with `blank`, and `flat` with `flat`. -/
def EdgeType.complement : EdgeType → EdgeType
  | flat => flat
  | tab => blank
  | blank => tab

@[simp] theorem EdgeType.complement_complement (e : EdgeType) :
    e.complement.complement = e := by cases e <;> rfl

theorem EdgeType.complement_involutive : Function.Involutive EdgeType.complement :=
  EdgeType.complement_complement

/-! ## Pieces, rotations and placements -/

/-- A jigsaw piece: four edges and an identifier. -/
structure Piece where
  top : EdgeType
  right : EdgeType
  bottom : EdgeType
  left : EdgeType
  id : ℕ
deriving DecidableEq, Repr

/-- The four admissible rotations (0°, 90°, 180°, 270° clockwise). -/
inductive Rotation where
  | r0 | r90 | r180 | r270
deriving DecidableEq, Repr, Fintype

/-- Effective edges `(top, right, bottom, left)` of a piece after a clockwise
rotation. -/
def rotEdges (r : Rotation) (p : Piece) : EdgeType × EdgeType × EdgeType × EdgeType :=
  match r with
  | .r0   => (p.top, p.right, p.bottom, p.left)
  | .r90  => (p.left, p.top, p.right, p.bottom)
  | .r180 => (p.bottom, p.left, p.top, p.right)
  | .r270 => (p.right, p.bottom, p.left, p.top)

/-- A piece placed at grid coordinate `(x, y)` with a rotation. -/
structure Placement where
  piece : Piece
  rot : Rotation
  x : ℕ
  y : ℕ
deriving DecidableEq, Repr

/-- The effective top edge of a placement. -/
def Placement.eTop (pl : Placement) : EdgeType := (rotEdges pl.rot pl.piece).1
/-- The effective right edge of a placement. -/
def Placement.eRight (pl : Placement) : EdgeType := (rotEdges pl.rot pl.piece).2.1
/-- The effective bottom edge of a placement. -/
def Placement.eBottom (pl : Placement) : EdgeType := (rotEdges pl.rot pl.piece).2.2.1
/-- The effective left edge of a placement. -/
def Placement.eLeft (pl : Placement) : EdgeType := (rotEdges pl.rot pl.piece).2.2.2

/-- Horizontal fit: the left piece's right edge complements the right piece's left
edge. -/
def HFits (a b : Placement) : Prop := a.eRight.complement = b.eLeft
/-- Vertical fit: the upper piece's bottom edge complements the lower piece's top
edge. -/
def VFits (a b : Placement) : Prop := a.eBottom.complement = b.eTop

/-! ## 3-CNF formulas -/

/-- A literal: a variable index with a polarity (`true` = positive). -/
structure Literal where
  var : ℕ
  pol : Bool
deriving DecidableEq, Repr

/-- A clause is a (nominally length-3) disjunction of literals. -/
abbrev Clause := List Literal

/-- A 3-CNF formula: a number of variables and a list of clauses. -/
structure CNF3 where
  numVars : ℕ
  clauses : List Clause
deriving Repr

/-- A literal is satisfied by an assignment when the variable's value equals the
polarity. -/
def Literal.satBy (σ : ℕ → Bool) (l : Literal) : Prop := σ l.var = l.pol
/-- A clause is satisfied when at least one literal is. -/
def Clause.satBy (σ : ℕ → Bool) (c : Clause) : Prop := ∃ l ∈ c, l.satBy σ
/-- A formula is satisfied when every clause is. -/
def CNF3.satBy (σ : ℕ → Bool) (φ : CNF3) : Prop := ∀ c ∈ φ.clauses, c.satBy σ
/-- A formula is satisfiable when some assignment satisfies it. -/
def Satisfiable (φ : CNF3) : Prop := ∃ σ : ℕ → Bool, φ.satBy σ

/-! ## Assemblies and puzzles -/

/-- Encode a boolean truth value as an edge: `true ↦ tab`, `false ↦ blank`. -/
def enc : Bool → EdgeType
  | true => .tab
  | false => .blank

/-- Decode an edge back to a boolean: `tab ↦ true`, everything else `↦ false`. -/
def decode : EdgeType → Bool
  | .tab => true
  | _ => false

@[simp] theorem decode_enc (b : Bool) : decode (enc b) = b := by cases b <;> rfl

/-- A board assigns a placement to every grid coordinate. -/
abbrev Board := ℕ → ℕ → Placement

/-- A rectangular `W × H` valid assembly: pieces sit at their coordinates, the
boundary edges are flat, and adjacent pieces fit. -/
structure IsRectAssembly (W H : ℕ) (b : Board) : Prop where
  coords : ∀ x y, x < W → y < H → (b x y).x = x ∧ (b x y).y = y
  hfit : ∀ x y, x + 1 < W → y < H → HFits (b x y) (b (x+1) y)
  vfit : ∀ x y, x < W → y + 1 < H → VFits (b x y) (b x (y+1))
  top_flat : ∀ x, x < W → 0 < H → (b x 0).eTop = .flat
  bot_flat : ∀ x, x < W → 0 < H → (b x (H-1)).eBottom = .flat
  left_flat : ∀ y, y < H → 0 < W → (b 0 y).eLeft = .flat
  right_flat : ∀ y, y < H → 0 < W → (b (W-1) y).eRight = .flat

/-- A puzzle: a bag of pieces, dimensions, and the clause constraints (each clause
piece's OR-fitting requirement). -/
structure Puzzle where
  pieces : Finset Piece
  width : ℕ
  height : ℕ
  clauses : List Clause

/-- A literal is satisfied by a board when the variable's top-row piece exposes the
matching bottom edge. -/
def Literal.satByBoard (b : Board) (l : Literal) : Prop :=
  (b l.var 0).eBottom = enc l.pol

/-- A clause is satisfied by a board when at least one literal is. -/
def Clause.satByBoard (b : Board) (c : Clause) : Prop := ∃ l ∈ c, l.satByBoard b

/-- The board only uses pieces drawn from the puzzle's bag. -/
def usesPieces (P : Puzzle) (b : Board) : Prop :=
  ∀ x y, x < P.width → y < P.height → (b x y).piece ∈ P.pieces

/-- A puzzle is solvable when some valid assembly, built from the available pieces,
satisfies every clause constraint. -/
def Solvable (P : Puzzle) : Prop :=
  ∃ b : Board, IsRectAssembly P.width P.height b ∧ usesPieces P b ∧
    (∀ c ∈ P.clauses, c.satByBoard b)

/-! ## The reduction -/

/-- The variable piece for variable `i` with truth value `v`: flat on three sides,
its bottom edge encodes `v`. -/
def varPiece (i : ℕ) (v : Bool) : Piece :=
  ⟨.flat, .flat, enc v, .flat, 2 * i + (if v then 0 else 1)⟩

/-- The base piece for truth value `v`: its top edge complements `enc v` (so it
mates with the variable piece above), and it is flat elsewhere. -/
def basePiece (v : Bool) : Piece :=
  ⟨(enc v).complement, .flat, .flat, .flat, 1000000 + (if v then 0 else 1)⟩

/-- The puzzle produced from a 3-CNF formula: an `n × 2` grid whose bag contains the
two variable pieces for each variable and the two base pieces, and whose clause
constraints are the formula's clauses. -/
def mkPuzzle (φ : CNF3) : Puzzle where
  pieces :=
    (Finset.range φ.numVars).biUnion (fun i => {varPiece i true, varPiece i false}) ∪
      {basePiece true, basePiece false}
  width := φ.numVars
  height := 2
  clauses := φ.clauses

/-- The board built from an assignment `σ`: variable pieces on the top row, base
pieces below. -/
def fwdBoard (σ : ℕ → Bool) : Board :=
  fun x y => if y = 0 then ⟨varPiece x (σ x), .r0, x, 0⟩ else ⟨basePiece (σ x), .r0, x, y⟩

/-! ## Correctness -/

/-- Forward direction: a satisfying assignment yields a solvable puzzle. -/
theorem forward (φ : CNF3) : Satisfiable φ → Solvable (mkPuzzle φ) := by
  intro h;
  use fwdBoard h.choose;
  refine' ⟨ _, _, _ ⟩;
  · constructor <;> simp +decide [ fwdBoard ];
    all_goals simp +decide [ mkPuzzle, HFits, VFits, Placement.eTop, Placement.eRight, Placement.eBottom, Placement.eLeft, rotEdges, varPiece, basePiece ];
    · grind;
    · intro x y hx hy; interval_cases y <;> simp +decide;
    · intro x y hx hy; rcases y with ( _ | _ | y ) <;> tauto;
    · intro y hy h; interval_cases y <;> simp +decide ;
    · intro y hy h; interval_cases y <;> simp +decide ;
  · intro x y hx hy;
    unfold mkPuzzle at *;
    unfold fwdBoard; split_ifs <;> simp_all +decide [ Finset.mem_biUnion ];
    · cases h.choose x <;> aesop;
    · cases h.choose x <;> tauto;
  · grind +locals

/-- Backward direction: a solvable puzzle yields a satisfying assignment. -/
theorem backward (φ : CNF3) : Solvable (mkPuzzle φ) → Satisfiable φ := by
  intro h;
  obtain ⟨b, hb⟩ := h;
  -- Define the assignment σ based on the bottom edges of the variable pieces in the top row.
  use fun i => decode (b i 0).eBottom;
  intro c hc; specialize hb; have := hb.2.2 c hc; obtain ⟨ l, hl₁, hl₂ ⟩ := this; use l; simp_all +decide [ Clause.satByBoard ] ;
  unfold Literal.satByBoard at hl₂; unfold Literal.satBy; aesop;

/-- **Correctness of the reduction.** A 3-CNF formula is satisfiable iff the puzzle
constructed from it is solvable. -/
theorem correctness (φ : CNF3) : Satisfiable φ ↔ Solvable (mkPuzzle φ) :=
  ⟨forward φ, backward φ⟩

/-! ## A concrete example

`(x₁ ∨ x₂ ∨ x₃) ∧ (¬x₁ ∨ x₂ ∨ ¬x₃)` over variables `0,1,2`. -/

/-- The example formula. -/
def exampleφ : CNF3 where
  numVars := 3
  clauses :=
    [ [⟨0, true⟩, ⟨1, true⟩, ⟨2, true⟩],
      [⟨0, false⟩, ⟨1, true⟩, ⟨2, false⟩] ]

theorem example_satisfiable : Satisfiable exampleφ := by
  use fun i => decide (i = 1);
  intro c hc; fin_cases hc <;> simp +decide [ Clause.satBy, Literal.satBy ];

theorem example_solvable : Solvable (mkPuzzle exampleφ) :=
  (correctness exampleφ).mp example_satisfiable

end JigsawSAT
